def mk(which):
    def f(p):
        if which==0: return -(p[0]*T**p[2]*np.log(1+p[1]*eps*T**p[3]) + p[4]*eps*T**p[5] + p[6]*eps**p[8]*T**p[7] + p[9]*eps**2)
        if which==1: return -(p[0]*T**p[2]*np.log(1+p[1]*eps*T**p[3]) + p[4]*eps*T**p[5] + p[6]*eps**2*T**p[7] + p[8]*eps**3*T**p[9])
        if which==2: return -(p[0]*T**p[2]*np.log(1+p[1]*eps) + p[4]*eps*T**p[5] + p[6]*eps**2*T**p[7]*np.exp(-p[8]*T))
        if which==3: return -(p[0]*T**p[2]*np.log(1+p[1]*eps*T**p[3]) + p[4]*eps*T**p[5] + p[6]*eps*T**p[7]*np.log(1+p[8]*eps))
    return f
